177	  public static RouterMetrics getMetrics() {
178	    if (!isInitialized.get()) {
179	      synchronized (RouterMetrics.class) {
180	        if (INSTANCE == null) {
181	          INSTANCE = DefaultMetricsSystem.instance().register("RouterMetrics",
182	              "Metrics for the Yarn Router", new RouterMetrics());
183	          isInitialized.set(true);
184	        }
185	      }
186	    }
187	    return INSTANCE;
188	  }
